#define TAU 6.2831853
#define tt iTime

// Vibrant custom color palette function
vec3 palette(float t) {
    return 0.5 + 0.5 * cos(TAU * (t + vec3(0.0, 0.33, 0.67)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Audio reactivity: sample from iChannel0
    float audio = texture(iChannel0, vec2(0.01, fragCoord.y / iResolution.y)).r;

    // Initialize color
    vec3 col = vec3(0.0);

    // Transformation parameters
    float scale = 1.0;
    float timeFactor = sin(tt * 0.5) * 0.5 + 1.0;

    // Iterative transformations
    for (float i = 0.0; i < 7.0; i++) {
        uv = abs(uv); // Mirror across axes
        uv += sin(length(uv) * TAU + tt + i) / (2.0 + sin(i + audio * 2.0)); // Distort UV with audio input
        uv *= 1.2; // Scale effect
        float angle = tt * 0.1 + i + audio; // Rotate with audio influence
        uv *= mat2(cos(angle), -sin(angle), sin(angle), cos(angle)); // Rotation matrix

        // Generate color using palette and sine-based patterns
        float intensity = 0.1 / (length(uv) + 0.1);
        col += palette(length(uv) + i * 0.2 + timeFactor) * intensity;
    }

    // Normalize and enhance glow
    col = pow(col, vec3(0.8)) + audio * 0.2; // Smooth color intensity and enhance with audio
    fragColor = vec4(col, 1.0); // Output final color
}
